script:
export const meta = {
  name: 'v5-ip-leak-sweep',
  description: 'Open every supplied image across all 100 tasks and find real-trademark or wrong-brand leaks, without flagging declared engineered defects',
  phases: [{ title: 'Sweep', detail: '20 agents x 5 tasks, ~73 images each' }],
}

const SCR = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/ipsweep'
const pad = n => String(n).padStart(2, '0')
const IDS = []
for (let i = 1; i <= 30; i++) IDS.push('PHOTO-' + pad(i))
for (let i = 1; i <= 15; i++) IDS.push('VECTOR-' + pad(i))
for (let i = 1; i <= 35; i++) IDS.push('LAYOUT-' + pad(i))
for (let i = 1; i <= 20; i++) IDS.push('MOTION-' + pad(i))
const BATCHES = []
for (let i = 0; i < IDS.length; i += 5) BATCHES.push(IDS.slice(i, i + 5))

const SCHEMA = {
  type: 'object',
  properties: {
    files_written: { type: 'array', items: { type: 'string' } },
    images_opened: { type: 'number' },
    leaks_found: { type: 'number' },
    notes: { type: 'string' },
  },
  required: ['files_written', 'images_opened'],
}

function prompt(ids) {
  return `You are running an intellectual-property and brand-integrity sweep on the supplied images of a creative benchmark. The corpus is meant to be IP-laundered: every brand in it is fictional, and no real company's trademark may appear anywhere in the pixels. Image models sometimes invent real branding unprompted, so this must be checked by LOOKING, not by reading prompts.

A real example of what you are hunting: one deli photograph came back with "KATZ'S DELICATESSEN, NEW YORK SINCE 1888" printed across the wrapping paper four times. That is a live trademark of a real business and cannot ship.

CRITICAL RULE, read twice. Many assets are DELIBERATELY degraded or inconsistent, because recovering or reconciling them IS the task. Each image below carries a "declared_defect" field. If what you see matches its declared defect, that is the benchmark working correctly and you must NOT report it. Never report: a damaged or clipped wordmark whose defect says so, a mark that survives only as a photograph, a text frame that overflows, a low-resolution export, a phone photo instead of a flat scan, a screen capture that is labelled a tone reference, or a colour that the defect says is off. You are ONLY looking for real-world brand contamination and marks belonging to a DIFFERENT business than this task's fictional brand.

For each task id in ${JSON.stringify(ids)}: Read ${SCR}/in/<TASK_ID>.json. It gives the fictional brand_name, its palette and typography, and an images list with local_path, role, priority, declared_defect and original_prompt.

Open the images with the Read tool, highest priority first. Work through as many as you can, and be honest in images_opened about how many you actually viewed. For each image look specifically at: printed packaging and wrappers, signage and shopfronts, clothing and footwear logos, equipment and plates and tools, screens and user interfaces, book and magazine covers, vehicles and number plates, posters on walls, and any small print.

Report ONLY these categories:
- "real_trademark": a genuine real-world company, product, team or institution name, logo or slogan is legible (e.g. a named delicatessen, a sportswear swoosh, a named software UI, a car maker's badge, a real magazine masthead).
- "foreign_brand": a legible business name or mark that is NOT this task's fictional brand and not a declared reference, for example another shop's name printed on the packaging this brand is supposed to own.
- "real_person": a recognisable real public figure.
- "brand_conflict": the image contradicts this brand's OWN stated palette or wordmark in a way the declared_defect does NOT account for.

For each finding give the filename, the category, exactly what text or mark you can see and where it sits in the frame, and a "regenerate_prompt": a rewritten generation prompt for that image that keeps the original subject, framing, lighting and any declared defect EXACTLY, but closes the leak, for example by specifying completely plain unprinted packaging and explicitly forbidding any brand name, logo, trademark or printed text anywhere in the frame.

Write ${SCR}/out/<TASK_ID>.json exactly as:
{"task_id":"...","images_opened":N,
 "findings":[{"filename":"...","category":"...","what_you_saw":"...","regenerate_prompt":"..."}]}
If a task is clean, write it with "findings": [].

Return only the structured summary. Do not modify any asset.`
}

phase('Sweep')
const results = await parallel(BATCHES.map((ids) => () =>
  agent(prompt(ids), { label: `sweep:${ids[0]}..${ids[ids.length-1]}`, phase: 'Sweep', agentType: 'general-purpose', schema: SCHEMA })
))
const ok = results.filter(Boolean)
return { batches: results.length, null_batches: results.length - ok.length,
  images: ok.reduce((s, r) => s + (r.images_opened || 0), 0),
  leaks: ok.reduce((s, r) => s + (r.leaks_found || 0), 0) }
